animation-speed-0.5.preferences_lua:
-- Generated by garage. Edit preferences.toml instead.
hl.config({
    input = {
        sensitivity = 0,
        accel_profile = "flat",
        natural_scroll = false,
        kb_layout = "us",
        repeat_rate = 25,
        repeat_delay = 600,
        touchpad = {
            tap_to_click = true,
            natural_scroll = true,
            disable_while_typing = true,
        },
    },
})

hl.config({
    general = { border_size = 0, col = {active_border = "rgba(666666ff)", inactive_border = "rgba(181818ff)"} },
    group = {
        col = {
            border_active = "rgba(666666ff)",
            border_inactive = "rgba(181818ff)",
            border_locked_active = "rgba(888888ff)",
            border_locked_inactive = "rgba(181818ff)",
        },
        groupbar = {
            col = {
                active = "rgba(666666ff)",
                inactive = "rgba(181818ff)",
                locked_active = "rgba(888888ff)",
                locked_inactive = "rgba(181818ff)",
            },
        },
    },
    decoration = {
        dim_strength = 0.08,
        rounding = 7,
        rounding_power = 3.37,
        active_opacity = 0.96,
        inactive_opacity = 0.96,
        fullscreen_opacity = 1.0,
        blur = {enabled = true, size = 6, passes = 2},
        shadow = {
            color = "rgba(00000066)",
            color_inactive = "rgba(00000040)",
        },
    },
})

if GLASS_AVAILABLE then
    hl.config({
        plugin = {
            kinetik_glass = {
                enabled = true,
                edge_width = 24,
                refraction = 0.7,
                edge_clarity = 0.75,
                highlight_opacity = 0.12,
                blur_passes = 4,
                blur_downscale = 0.25,
                layer_rounding = 7,
                corner_power = 3.37,
                tint = "rgba(1c1c1eff)",
                tint_opacity = 0.2,
                frame_highlight_opacity = 0.1,
                frame_border_opacity = 0.05,
                dispersion = 0,
                saturation = 0.5,
            },
        },
    })
end

if HYPREXPO_AVAILABLE then
    hl.config({
        plugin = {
            hyprexpo = {
                tile_rounding = 7,
                tile_rounding_power = 3.37,
            },
        },
    })
end

hl.config({animations = {enabled = true}})
hl.animation({ leaf = "global", enabled = true, speed = 6, bezier = "workspaceEase" })
hl.animation({ leaf = "layers", enabled = true, speed = 4.8, bezier = "workspaceEase" })
hl.animation({ leaf = "workspaces", enabled = true, speed = 6, bezier = "workspaceEase", style = "slide" })

